import black


def test_single_argument_def_keeps_a_trailing_comma():
    src = 'def very_long_function_name_that_forces_a_split(argument_name_that_is_long) -> ReturnType:\n    pass\n'
    try:
        mode = black.Mode(line_length=88)
        formatted = black.format_str(src, mode=mode)
    except AttributeError:
        formatted = black.format_str(src, line_length=88)
    assert "argument_name_that_is_long," in formatted
